def next_url():
    t, q = heap.pop_min()                # earliest allowed fetch
    sleep_until(t)
    url = back[q].pop()
    return q, url

def complete(q, elapsed, status):
    delay = max(robots.crawl_delay(host_of[q]), 10 * elapsed, 1.0)
    if status in (429, 503): delay = backoff(host_of[q])   # exp, cap 1h
    if back[q].empty(): refill(q)
    heap.push(now() + delay, q)

def refill(q):
    while True:
        url = pick_front_queue_biased().pop()
        h = host(url)
        if h in host_to_q: back[host_to_q[h]].push(url)
        else: host_to_q[h] = q; host_of[q] = h; back[q].push(url); return

def simhash(text):
    v = [0] * 64
    for shingle, w in features(text):     # e.g. 3-word shingles, tf weights
        h = hash64(shingle)
        for i in range(64):
            v[i] += w if (h >> i) & 1 else -w
    return sum(1 << i for i in range(64) if v[i] > 0)

def is_near_dup(fp):
    for table in permuted_tables:          # 4 tables, 16-bit prefix each
        for cand in table.lookup(prefix(table.permute(fp))):
            if popcount(cand ^ fp) <= 3: return True
    return False
